import type { EmbeddingMetadata } from '../config/types.js'

/**
 * The metadata as it comes back out of the jsonb column beside the vector.
 *
 * Every entry is optional because the column holds whatever was written to it
 * rather than a value the type system has checked: an embedding generated by
 * an older plugin version, or a row a manual write shaped itself, can be
 * missing any of these. The field component renders the entries that are there.
 */
export type EmbeddingDisplayMetadata = Partial<EmbeddingMetadata>

/** How much of an embedding value may cross to the browser. */
export type EmbeddingDisplayOptions = {
  showVector: boolean
  showMetadata: boolean
}

/**
 * The projection of an embedding value the browser receives in place of the
 * stored `StoredEmbedding`.
 *
 * `isSet` is load-bearing beyond display: the admin UI's item-form submit
 * transform skips any value carrying an `isSet` key, which is what stops a
 * redacted embedding being sent back as a write. Nothing is lost by that — an
 * embedding is a plugin output the admin UI never writes (ADR-0045), and a
 * field with `allowManualWrites` is still written from application code.
 */
export type SerializedEmbedding = {
  isSet: boolean
  /** The stored vector's length, whether or not {@link vector} carries it. */
  dimensions: number | null
  /** The vector itself, present only when the field sets `ui.showVector`. */
  vector: number[] | null
  /** Present only when the field sets `ui.showMetadata` (the default). */
  metadata: EmbeddingDisplayMetadata | null
}

type EmbeddingSource = {
  isSet: boolean
  dimensions: number | null
  vector: readonly unknown[] | null
  metadata: unknown
}

const ABSENT: EmbeddingSource = { isSet: false, dimensions: null, vector: null, metadata: null }

/**
 * Read either shape an embedding value arrives in: the stored
 * `{ vector, metadata }`, or a {@link SerializedEmbedding} that has already
 * been through {@link redactEmbeddingForClient} — a form re-serialising its own
 * initial data hands back the latter.
 */
function readSource(value: unknown): EmbeddingSource {
  if (typeof value !== 'object' || value === null) return ABSENT

  const metadata = Reflect.get(value, 'metadata')
  const vector = Reflect.get(value, 'vector')
  if (Array.isArray(vector)) {
    return { isSet: true, dimensions: vector.length, vector, metadata }
  }

  if (typeof Reflect.get(value, 'isSet') !== 'boolean') return ABSENT
  const dimensions = Reflect.get(value, 'dimensions')
  return {
    isSet: Reflect.get(value, 'isSet') === true,
    dimensions: typeof dimensions === 'number' ? dimensions : null,
    vector: null,
    metadata,
  }
}

function readMetadata(value: unknown): EmbeddingDisplayMetadata | null {
  if (typeof value !== 'object' || value === null) return null

  const metadata: EmbeddingDisplayMetadata = {}
  const model = Reflect.get(value, 'model')
  const provider = Reflect.get(value, 'provider')
  const dimensions = Reflect.get(value, 'dimensions')
  const generatedAt = Reflect.get(value, 'generatedAt')
  const sourceHash = Reflect.get(value, 'sourceHash')

  if (typeof model === 'string') metadata.model = model
  if (typeof provider === 'string') metadata.provider = provider
  if (typeof dimensions === 'number') metadata.dimensions = dimensions
  if (typeof generatedAt === 'string') metadata.generatedAt = generatedAt
  if (typeof sourceHash === 'string') metadata.sourceHash = sourceHash

  return Object.keys(metadata).length === 0 ? null : metadata
}

function readVector(entries: readonly unknown[]): number[] | null {
  const vector: number[] = []
  for (const entry of entries) {
    if (typeof entry !== 'number') return null
    vector.push(entry)
  }
  return vector
}

/**
 * Reduce an embedding value to what the field's `ui` options say may be shown.
 *
 * Installed as the field's `ui.valueForClientSerialization`, so a vector the
 * admin UI does not display is not serialised into the page either. The field
 * component applies the same function to whatever value reaches it, since a
 * standalone form or a list table can hand over one that never passed through
 * this on the server.
 */
export function redactEmbeddingForClient(
  value: unknown,
  { showVector, showMetadata }: EmbeddingDisplayOptions,
): SerializedEmbedding {
  const source = readSource(value)
  return {
    isSet: source.isSet,
    dimensions: source.dimensions,
    vector: showVector && source.vector !== null ? readVector(source.vector) : null,
    metadata: showMetadata ? readMetadata(source.metadata) : null,
  }
}
